sys_variable_value.value:
(function execute(inputs, outputs) {

var token_primary = inputs.token;
var payload_primary = inputs.payload;

try { 
    var tokenBearer = token_primary;
    var r = new sn_ws.RESTMessageV2('x_asscs_integra.SAP - ServiceNow', 'adicionarBPFiador');
    r.setStringParameterNoEscape('token', tokenBearer);
    r.setRequestHeader('Authorization', 'Bearer ' + tokenBearer);
    r.setRequestHeader('Content-Type', 'application/json');

    //var requestBody = JSON.stringify(payload_primary);
    var requestBody = payload_primary;
    r.setRequestBody(requestBody);

    gs.info('Integra+ Contrato adicionar BP Fiador ' + requestBody);

    var response = r.execute();
    var responseBody = response.getBody();
    var httpStatus = response.getStatusCode();

    gs.info('*Integra+ Http Status: ' + httpStatus);
    gs.info('*Integra+ responseBody : ' + responseBody);


      if (httpStatus == 200 || httpStatus == 201 || httpStatus == 202) {

        var payloadAnswer = JSON.parse(responseBody);
        var contractNumber = payloadAnswer.ContractNumber;
        gs.info("Número do contrato: " + contractNumber);
        outputs.contractnumber = contractNumber;

    } else {
        var parsedResponse = JSON.parse(responseBody);

        var messages = [];
        // Percorrendo as mensagens
        parsedResponse.ReturnMessages.forEach(function(item) {
            if (item.Message) {
                messages.push(item.Message);
            }
        });
        var errorMsg = "";

        messages.forEach(function(msg, index) {
            var currentMsg = "Error " + (index + 1) + ": " + msg;
            gs.info(currentMsg);
            errorMsg += currentMsg + "\n";
        });
        outputs.errormsg = errorMsg;
        outputs.httpstatusanswer = httpStatus;
    }
}
catch(ex) {
 var message = ex.message;
}

})(inputs, outputs);

